import math

def control(obs):
    lm = obs.get("local_map", {})
    left = lm.get("left_rail", [])
    right = lm.get("right_rail", [])
    def interp(points, u):
        pts = sorted(points, key=lambda p: p[0])
        if not pts:
            return None
        for a, b in zip(pts, pts[1:]):
            if a[0] <= u <= b[0]:
                f = (u-a[0])/(b[0]-a[0]) if b[0] != a[0] else 0
                return a[1] + f*(b[1]-a[1])
        return min(pts, key=lambda p: abs(p[0]-u))[1]
    target_u = 3.0
    lv, rv = interp(left, target_u), interp(right, target_u)
    steer = 0.0
    if lv is not None and rv is not None:
        center = (lv + rv) * 0.5
        steer += -13.0 * center
    hitch = float(obs.get("hitch_deg", 0.0))
    steer += 1.15 * hitch
    steer = max(-26.0, min(26.0, steer))
    return (steer, -0.42, 180)

